<script setup lang="ts">
import {ref,watch} from 'vue'
import {api} from '../api'
import {number,time} from '../format'
import {entryOutcome,type EntryWindow,type EntrySummary,type EntryDetail} from '../quantEntry'
const props=defineProps<{window?:EntryWindow;firstAt?:string|null;version?:string|null}>()
const selected=ref<EntrySummary|null>(null),detail=ref<EntryDetail|null>(null),error=ref(''),loading=ref(false);let generation=0
watch(()=>props.window?.records,rows=>{if(selected.value&&!rows?.some(r=>r.id===selected.value!.id)){generation++;selected.value=null;detail.value=null;loading.value=false}})
async function open(row:EntrySummary){if(selected.value?.id===row.id){generation++;selected.value=null;detail.value=null;loading.value=false;return}selected.value=row;detail.value=null;error.value='';loading.value=true;const id=++generation;try{const result=await api<EntryDetail>(`/api/quant/entry-review/${encodeURIComponent(row.id)}`);if(id===generation)detail.value=result}catch(e){if(id===generation)error.value=e instanceof Error?e.message:String(e)}finally{if(id===generation)loading.value=false}}
</script>
<template><details class="entry-reviews"><summary>逐次开仓复核 · {{window?.records.length??0}}条</summary><p v-if="version">当前执行实现 {{version}}。策略条件与原批准上限保持；此前入场不追改为此实现。</p><p>对比原批准上限、未约束重算方案和实际采用方案。未约束方案只用于诊断，未按其扩大成交。与成交、现金在同一事务保存。</p><p v-if="firstAt">完整复核从{{time(firstAt)}}起有记录；更早的取消日志缺少前后值，保留无法精确归因。</p><p v-if="window?.truncated" role="alert" class="radar-notice">只显示本日最近200条复核，较早记录仍在本地数据库中；此列表不是当日完整数量。</p><p v-if="!window?.records.length" class="empty">本报告尚无逐次复核样本，等待后续意向；不补造历史复核或测试成交。</p>
<div v-else class="table-scroll"><table><thead><tr><th>复核时间 / 合约</th><th>结果</th><th>原批准数量 → 采用数量</th><th>具体原因</th><th>前后值</th></tr></thead><tbody><tr v-for="row in window.records" :key="row.id"><td>{{time(row.at)}}<small>{{row.symbol}} · {{row.direction==='Long'?'多':'空'}}</small></td><td>{{entryOutcome(row.outcome)}}<small v-if="row.capped">已按原批准上限约束</small></td><td>{{number(row.values.find(v=>v.key==='Quantity')?.approved,6)}} → {{number(row.values.find(v=>v.key==='Quantity')?.selected,6)}}</td><td class="decision-reason">{{row.reason}}</td><td><button class="text-button" @click="open(row)">{{selected?.id===row.id?'收起':'展开'}}</button></td></tr></tbody></table></div>
<section v-if="selected" class="detail"><h3>{{selected.symbol}} · {{entryOutcome(selected.outcome)}}</h3><p>{{selected.reason}} · {{selected.version}} · 账户版本{{selected.revision}}</p><div class="table-scroll"><table><thead><tr><th>检查项</th><th>原批准</th><th>未约束重算</th><th>实际采用</th><th>上限核验</th></tr></thead><tbody><tr v-for="value in selected.values" :key="value.key"><td>{{value.name}}</td><td>{{number(value.approved,8)}}</td><td>{{number(value.proposed,8)}}</td><td>{{number(value.selected,8)}}</td><td>{{value.passed==null?'未核验 / 仅展示':value.passed?'通过':'未通过'}}<small>{{value.meaning}}</small></td></tr></tbody></table></div><p v-if="loading">读取本地原始资料…</p><p v-if="error" role="alert">{{error}}</p><template v-if="detail"><p>意向{{time(detail.intent.createdAt)}}；当前报价来源{{time(detail.evidence.market?.priceAt)}} / 接收{{time(detail.evidence.market?.priceReceivedAt)}}；盘口来源{{time(selected.bookAt)}}。其他意向预留{{number(detail.evidence.cashReserved,6)}} U。</p><p v-for="check in detail.selected?.checks.filter(c=>!c.passed)" :key="check.key">未通过：{{check.name}}，实际{{number(check.actual,8)}}，要求{{check.requirement}}。</p><p>原始信号{{detail.evidence.signalVerified?'已通过存档复算':'未核验'}}；保存{{detail.evidence.frames.length}}份相关性小时片段，用于本地重算，而非从当前行情补写。</p></template><p><a :href="`/api/quant/entry-review/${selected.id}`" target="_blank" rel="noopener">查看本次完整原始JSON →</a></p></section></details></template>
<style scoped>.entry-reviews{border-top:1px solid #293b46;padding:16px 0}.entry-reviews summary{cursor:pointer}.entry-reviews td{white-space:normal;min-width:90px}.entry-reviews td small{overflow-wrap:anywhere}.entry-reviews h3{font-size:14px}</style>
